  [reuters, publicParty] <- createParties ["Reuters", "PublicParty"]

  let
    toTime d = time d 0 0 0
    observations = Map.fromList $ fmap (\(d, v) -> (toTime d, v))
      [ (date 2019 Jan 16, -0.00311)
